widget.css:
:root { color-scheme: dark; font-family: -apple-system, BlinkMacSystemFont, sans-serif; container-type: size; }
* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; background: transparent; }
.metric { width: 100%; height: 100%; padding: 7px 9px; border-radius: 13px; background: rgba(255,255,255,.09); color: rgba(255,255,255,.92); display: flex; flex-direction: column; justify-content: space-between; }
.metric-head { display: flex; align-items: center; justify-content: space-between; font-size: 10px; color: rgba(255,255,255,.52); }
button { width: 18px; height: 18px; padding: 0; border: 0; background: transparent; color: rgba(255,255,255,.42); font: 12px -apple-system; cursor: pointer; }
button:hover { color: rgba(255,255,255,.86); }
.metric-main { display: flex; align-items: end; justify-content: space-between; gap: 7px; min-width: 0; }
.metric-value { font: 600 17px ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: 0; white-space: nowrap; }
.metric-trend { display: none; height: 17px; flex: 1; align-items: end; gap: 2px; opacity: .48; }
.metric-trend i { flex: 1; min-width: 1px; max-width: 4px; border-radius: 1px 1px 0 0; background: currentColor; }
.metric-detail { display: none; font-size: 9px; color: rgba(255,255,255,.42); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.metric-track { height: 2px; border-radius: 1px; background: rgba(255,255,255,.12); overflow: hidden; }
.metric-track i { display: block; width: 0; height: 100%; background: rgba(255,255,255,.72); transition: width .24s ease, background .24s ease; }
@container (max-width: 70px) { button, .metric-track { display: none; } .metric { padding: 8px 7px; } .metric-value { font-size: 15px; } }
@container (min-width: 96px) { .metric-trend { display: flex; } }
@container (min-width: 150px) { .metric-detail { display: block; } }

widget.javascript:
const value = document.getElementById('value');
const name = document.getElementById('name');
const detail = document.getElementById('detail');
const trend = document.getElementById('trend');
const bar = document.getElementById('bar');
function render(result) {
  if (!result?.ok || !result.state) return false;
  const percent = Math.round(Math.max(0, Math.min(1, result.state.fraction || 0)) * 100);
  name.textContent = result.state.name || window.__notchWidget.name;
  value.textContent = percent + '%';
  detail.textContent = result.state.detail || '';
  trend.replaceChildren(...(result.state.trend || []).map(point => {
    const bar = document.createElement('i');
    bar.style.height = Math.max(2, Math.round(point * 17)) + 'px';
    return bar;
  }));
  bar.style.width = percent + '%';
  bar.style.background = percent >= 90 ? 'rgba(255,115,96,.9)' : percent >= 75 ? 'rgba(236,190,92,.9)' : 'rgba(255,255,255,.72)';
  return true;
}
async function refresh() {
  const result = await notchany.invoke('refresh', null);
  if (!render(result) && !notchany.state) value.textContent = '--%';
}
document.getElementById('refresh').addEventListener('click', refresh);
let timer;
notchany.addEventListener('visibilitychange', () => {
  clearInterval(timer);
  if (notchany.visible) { refresh(); timer = setInterval(refresh, 5000); }
});
notchany.addEventListener('statechange', event => render(event.state));
if (notchany.state) render(notchany.state);
if (notchany.visible) { refresh(); timer = setInterval(refresh, 5000); }
